// E.164-ish: optional +, digits/spaces/dashes/parens, 7–15 digits total
const PHONE_RE = /^\+?[\d\s\-().]{7,20}$/;

function validateField(key) {
  const { input, error } = fields[key];
  let message = '';

  if (key === 'name') {
    if (!input.value.trim()) message = 'Error: Full name is required.';
  } else if (key === 'email') {
    if (!input.value.trim()) {
      message = 'Error: Email address is required.';
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(input.value.trim())) {
      message = 'Error: Enter a valid email address, e.g. name@example.com.';
    }
  } else if (key === 'phone') {
    if (input.value.trim() && !PHONE_RE.test(input.value.trim())) {
      message = 'Error: Enter a valid phone number, e.g. +1 (555) 123-4567.';
    }
  }

  if (message) {
    input.setAttribute('aria-invalid', 'true');
    error.textContent = message;
    error.classList.add('visible');
  } else {
    input.removeAttribute('aria-invalid');
    error.textContent = '';
    error.classList.remove('visible');
  }

  return message;
}

