*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-page:        #0f1117;
  --bg-card:        #1a1d27;
  --bg-input:       #12141e;
  --border:         #2e3248;
  --border-focus:   #6c7aff;
  --border-error:   #f05a5a;
  --text-primary:   #e8eaf0;
  --text-secondary: #9197b3;
  --text-placeholder: #4e546e;
  --accent:         #6c7aff;
  --accent-hover:   #8490ff;
  --btn-bg:         #4a54de;
  --btn-bg-hover:   #5562e8;
  --error:          #f05a5a;
  --success:        #3ecf8e;
  --radius:         8px;
  --transition:     0.18s ease;
}

/* ── Skip link ── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 100;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  border-radius: var(--radius);
  font-weight: 600;
  text-decoration: none;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ── Page layout ── */
body {
  min-height: 100vh;
  background: var(--bg-page);
  color: var(--text-primary);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  display: flex;
  flex-direction: column;
}

header {
  border-bottom: 1px solid var(--border);
  padding: 1rem 1.5rem;
}

header .site-name {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: 0.02em;
}

main {
  flex: 1;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 3rem 1rem 4rem;
}

/* ── Card ── */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 2.5rem 2rem;
  width: 100%;
  max-width: 480px;
}

.card-header { margin-bottom: 2rem; }

.card-header h1 {
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1.25;
  margin-bottom: 0.4rem;
}

.card-header p {
  color: var(--text-secondary);
  font-size: 0.9375rem;
}

/* Required legend */
.required-legend {
  font-size: 0.85rem;
  color: var(--text-secondary);
  margin-bottom: 1.5rem;
}
.required-legend .req-star {
  color: var(--error);
  font-weight: 700;
  margin-right: 0.2em;
}

/* ── Form fields ── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  margin-bottom: 1.375rem;
}

.form-field label {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-primary);
  letter-spacing: 0.01em;
}

.req-marker {
  color: var(--error);
  font-weight: 700;
  margin-left: 0.2em;
  line-height: 1;
}

.form-field input {
  background: var(--bg-input);
  border: 1.5px solid var(--border);
  border-radius: var(--radius);
  color: var(--text-primary);
  font-size: 1rem;
  padding: 0.65rem 0.85rem;
  transition: border-color var(--transition), box-shadow var(--transition);
  width: 100%;
  outline: none;
}

.form-field input::placeholder { color: var(--text-placeholder); }

.form-field input:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(108, 122, 255, 0.25);
}

/* Invalid state */
.form-field input[aria-invalid="true"] {
  border-color: var(--border-error);
}
.form-field input[aria-invalid="true"]:focus {
  box-shadow: 0 0 0 3px rgba(240, 90, 90, 0.25);
}

/* Helper text */
.field-help {
  font-size: 0.8275rem;
  color: var(--text-secondary);
  line-height: 1.45;
}

/* Error text */
.field-error {
  font-size: 0.8275rem;
  color: var(--error);
  line-height: 1.45;
  display: none;
}

.field-error.visible { display: block; }

/* ── Submit button ── */
.btn-submit {
  width: 100%;
  margin-top: 0.5rem;
  padding: 0.75rem 1.25rem;
  background: var(--btn-bg);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  letter-spacing: 0.02em;
  transition: background var(--transition), box-shadow var(--transition);
  outline: none;
}

.btn-submit:hover { background: var(--btn-bg-hover); }

.btn-submit:focus-visible {
  box-shadow: 0 0 0 3px rgba(108, 122, 255, 0.45);
}

/* ── Status regions ── */
[role="status"],
[role="alert"] {
  font-size: 0.9rem;
  border-radius: var(--radius);
  padding: 0;
  margin-top: 0;
  line-height: 1.5;
}

.status-success {
  background: rgba(62, 207, 142, 0.1);
  border: 1px solid rgba(62, 207, 142, 0.35);
  color: var(--success);
  padding: 0.75rem 1rem;
  border-radius: var(--radius);
  margin-top: 1rem;
}

.status-error-summary {
  background: rgba(240, 90, 90, 0.08);
  border: 1px solid rgba(240, 90, 90, 0.35);
  color: var(--error);
  padding: 0.75rem 1rem;
  border-radius: var(--radius);
  margin-bottom: 1.25rem;
}

/* Hide live region when empty */
[role="status"]:empty,
[role="alert"]:empty { display: none; }

/* ── Forced colors (high-contrast) ── */
@media (forced-colors: active) {
  .form-field input { border: 2px solid ButtonText; }
  .form-field input:focus { outline: 2px solid Highlight; }
  .btn-submit { forced-color-adjust: none; background: Highlight; color: HighlightText; }
  .req-marker, .field-error { forced-color-adjust: none; color: LinkText; }
}

/* ── Reflow / narrow viewport ── */
@media (max-width: 480px) {
  .card { padding: 1.75rem 1.25rem; border-radius: 0; border-left: none; border-right: none; }
  main { padding: 0; }
}

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}
